package biz

import (
	"encoding/json"
	"time"
)

// ExperienceReport is a per-invocation diagnostic report generated by the
// skill intelligence subsystem. It captures structured analysis of a single
// skill invocation: success/failure outcome, failure tags, a 0-100 score,
// natural language summaries, and the selection snapshot that led to this
// skill being chosen.
//
// This type is distinct from the ExperienceReport in internal/biz/types/skill_health.go,
// which is an aggregate report used by skills-butler.
type ExperienceReport struct {
	ID                    string
	TenantID              string
	SessionID             string
	InvocationID          string
	SkillID               string
	SkillName             string
	IsSuccess             bool
	Score                 int
	FailureTags           []string
	FlowSummary           string
	OptimizationAdvice    string
	SelectionSnapshot     json.RawMessage
	RootCauseAnalysis     string
	SuggestedFix          string
	GeneratedSuggestionID *string
	CreatedAt             time.Time
}

// Failure tag constants for ExperienceReport.FailureTags.
const (
	FailureTagParamMismatch        = "param_mismatch"
	FailureTagWrongToolChoice      = "wrong_tool_choice"
	FailureTagToolTimeout          = "tool_timeout"
	FailureTagToolAPIError         = "tool_api_error"
	FailureTagContextOverflow      = "context_overflow"
	FailureTagInstructionAmbiguity = "instruction_ambiguity"
	FailureTagUserCancelled        = "user_cancelled"
	FailureTagUnknown              = "unknown"
)
